    elapsedW = 0;
  }
  final tailBudget = remain - elapsedW;

  final (desc, badge, meta, diff) = _squeezeCardTail(s, tailBudget);
  final body = headRaw + _paintCardTail(c, phase, (desc, badge, meta, diff), paint);
